import { useState } from 'react'
import { Link } from 'react-router-dom'
import { useSelector } from 'react-redux'
import { HeaderBar } from './styles'
import logo from '../../../assets/images.nova/logo.svg'
import { LinkCart } from '../styles'
import { RootState } from '../../../store/store'
import { CarrinhoContainer } from '../../Carrinho/styles' // Importe os estilos do carrinho

const HeaderAlternativo = () => {
  const [isCarrinhoOpen, setIsCarrinhoOpen] = useState(false) // Estado para controlar a visibilidade do carrinho
  const itensNoCarrinho = useSelector(
    (state: RootState) => state.carrinho.itens
  )

  // Função para alternar o carrinho
  const toggleCarrinho = () => {
    setIsCarrinhoOpen(!isCarrinhoOpen)
  }

  return (
    <HeaderBar>
      <div>
        <h3>Restaurante</h3>
        <Link to="/">
          <img src={logo} alt="eFood" />
        </Link>
        <LinkCart onClick={toggleCarrinho}>
          <p>{itensNoCarrinho.length} - produto(s)</p>
        </LinkCart>
      </div>

      {/* Passando a propriedade isOpen para controlar a visibilidade */}
      {isCarrinhoOpen && (
        <CarrinhoContainer isOpen={isCarrinhoOpen}>
          {' '}
          {/* Passando a propriedade isOpen */}
          {/* Coloque o conteúdo do carrinho aqui, como a lista de itens */}
          <h3>Carrinho</h3>
          {/* Adicione os itens do carrinho, a descrição, e o botão de fechar aqui */}
        </CarrinhoContainer>
      )}
    </HeaderBar>
  )
}

export default HeaderAlternativo
